def dfs(current_loc, current_time, remaining, steps):
    global best_itinerary, best_count
    # Record current itinerary (may be terminal)
    if len(steps) > 0:
        visited = sum(1 for s in steps if s.startswith('You meet '))
        if visited > best_count:
            best_count = visited
            best_itinerary = steps[:]
    # Try to add another friend
    for i, fr in enumerate(remaining):
        travel_time = travel[current_loc][fr['location']]
        arrival = current_time + travel_time
        meeting_start = max(arrival, fr['window_start'])
        meeting_end = meeting_start + fr['min_meet']
        if meeting_end <= fr['window_end']:
            new_steps = steps[:]
            # travel step
            arrival_str = minutes_to_str(arrival)
            new_steps.append(f"You travel to {fr['location']} in {travel_time} minutes and arrive at {arrival_str}.")
            # wait step if needed before meeting
            if arrival < meeting_start:
                wait_str = minutes_to_str(meeting_start)
                new_steps.append(f"You wait until {wait_str}.")
            # meet step
            start_str = minutes_to_str(meeting_start)
            end_str = minutes_to_str(meeting_end)
            new_steps.append(f"You meet {fr['name']} from {start_str} to {end_str}.")
            # recurse
            dfs(fr['location'], meeting_end, remaining[:i]+remaining[i+1:], new_steps)

