def travel_time(a, b):
    return travel.get((a, b), 0)

def fmt(t):
    return t.strftime("%-I:%M%p")

def schedule_order(order):
    """Return (feasible, steps, finish_time) for a given order of friends."""
    loc = START_LOC
    time = START_TIME
    steps = [f"You start at {START_LOC} at {fmt(time)}."]
    for name in order:
        f = friends[name]
        # travel
        tmin = travel_time(loc, f["location"])
        if tmin > 0:
            arrive = time + timedelta(minutes=tmin)
            steps.append(f"You travel to {f['location']} in {tmin} minutes and arrive at {fmt(arrive)}.")
        else:
            arrive = time

        # wait if early
        meet_start = max(arrive, f["avail_start"])
        if meet_start > arrive:
            steps.append(f"You wait until {fmt(meet_start)}.")

        meet_end = meet_start + timedelta(minutes=f["min_meet"])

        # check window
        if meet_end > f["avail_end"]:
            return False, [], None  # infeasible

        steps.append(f"You meet {name} from {fmt(meet_start)} to {fmt(meet_end)}.")
        # update location & time
        loc = f["location"]
        time = meet_end
    return True, steps, time

