def to_minutes(t):
    # t like "9:00AM"
    parts = t[:-2].split(':')
    hour = int(parts[0])
    minute = int(parts[1])
    suffix = t[-2:]
    if suffix == 'PM' and hour != 12:
        hour += 12
    if suffix == 'AM' and hour == 12:
        hour = 0
    return hour * 60 + minute

