import itertools
from datetime import datetime, timedelta

# Define travel times (minutes) between locations
travel = {
    ('Richmond District', 'Pacific Heights'): 10,
    ('Richmond District', 'Marina District'): 9,
    ('Pacific Heights', 'Richmond District'): 12,
    ('Pacific Heights', 'Marina District'): 6,
    ('Marina District', 'Richmond District'): 11,
    ('Marina District', 'Pacific Heights'): 7,
}

# Friends data: location, availability window, required meeting minutes
friends = {
    'Jessica': {
        'location': 'Pacific Heights',
        'window_start': '3:30PM',
        'window_end': '4:45PM',
        'duration': 45,
    },
    'Carol': {
        'location': 'Marina District',
        'window_start': '11:30AM',
        'window_end': '3:00PM',
        'duration': 60,
    },
}

def parse(t):
    return datetime.strptime(t, "%I:%M%p")

def fmt(dt):
    return dt.strftime("%-I:%M%p").replace(' ', '')

def add_minutes(dt, mins):
    return dt + timedelta(minutes=mins)

def build_itinerary(order):
    steps = []
    cur_loc = 'Richmond District'
    cur_time = parse('9:00AM')
    steps.append(f'You start at Richmond District at {fmt(cur_time)}.')

    for friend in order:
        friend_info = friends[friend]
        travel_time = travel[(cur_loc, friend_info['location'])]
        arrive_time = add_minutes(cur_time, travel_time)
        steps.append(
            f'You travel to {friend_info["location"]} in {travel_time} minutes and arrive at {fmt(arrive_time)}.'
        )
        # Determine meeting start time
        window_start = parse(friend_info['window_start'])
        window_end = parse(friend_info['window_end'])
        meeting_start = max(arrive_time, window_start)
        if meeting_start > arrive_time:
            steps.append(f'You wait until {fmt(meeting_start)}.')
        meeting_end = add_minutes(meeting_start, friend_info['duration'])
        if meeting_end > window_end:
            return None  # infeasible
        steps.append(
            f'You meet {friend} from {fmt(meeting_start)} to {fmt(meeting_end)}.'
        )
        # Update for next leg
        cur_loc = friend_info['location']
        cur_time = meeting_end
    return steps

# Try all permutations of meeting order
for perm in itertools.permutations(friends.keys()):
    itinerary = build_itinerary(perm)
    if itinerary:
        print(itinerary)
        break
